export const roomBets=Object.freeze({none:{name:'내기 없음'},starbucks:{name:'스타벅스 아이스 아메리카노',image:'gift-starbucks.png',url:'https://gift.kakao.com/product/11062288'},mgc:{name:'메가커피 아이스 아메리카노',image:'gift-mgc.png',url:'https://gift.kakao.com/product/11561213'},compose:{name:'컴포즈커피 아이스 아메리카노',image:'gift-compose.png',url:'https://gift.kakao.com/product/11983723'}});
export const betKeys=Object.keys(roomBets);
export function betField(key='none'){return `<label class="rummi-bet-select"><span>내기 선택</span><select name="bet" aria-label="내기 선택">${Object.entries(roomBets).map(([value,bet])=>`<option value="${value}" ${value===key?'selected':''}>${bet.name}</option>`).join('')}</select></label>`;}
export function betBadge(key){const bet=roomBets[key]||roomBets.none;return `<span class="rummi-bet-badge">${bet.image?`<img src="${new URL('../assets/'+bet.image,import.meta.url).href}" width="28" height="28" alt="">`:''}<span>${bet.name}</span></span>`;}
export function betNotice(key){const bet=roomBets[key]||roomBets.none;return `<p class="rummi-bet-notice">${bet.image?`이번 경기에는 <img src="${new URL('../assets/'+bet.image,import.meta.url).href}" width="36" height="36" alt=""><strong>${bet.name}</strong> 내기가 걸려 있습니다.`:'이번 경기는 내기 없이 진행합니다.'}</p>`;}
